"""Property-based test patterns (Hypothesis). Generated by `eos scaffold property-python`; yours to edit.

Replace the toy functions with your own code. Good targets: parsers/serialisers (round trip), money maths
(invariants), anything with a slow-but-obvious reference implementation (oracle). Background:
.eos/packs/ref/testing/property-fuzz.md
Dev dep: uv add --dev hypothesis
Profiles: with CI set, Hypothesis loads its built-in "ci" profile (derandomized, no deadline, prints a
reproduction blob). Longer nightly run: pytest --hypothesis-profile=nightly (the profile must be registered
in tests/conftest.py, as the tests-python scaffold does:
settings.register_profile("nightly", max_examples=2000)).
"""

import json
from decimal import Decimal

from hypothesis import example, given
from hypothesis import strategies as st


# --- toy code under test (replace with imports from your package) ------------------------------------------
def split_amount(total_cents: int, parts: int) -> list[int]:
    """Split money into `parts` shares that differ by at most one cent and add up exactly."""
    base, rest = divmod(total_cents, parts)
    return [base + (1 if i < rest else 0) for i in range(parts)]


def encode(data: dict) -> str:
    return json.dumps(data, sort_keys=True)


def decode(text: str) -> dict:
    return json.loads(text)


# --- 1. invariants: properties that hold for every valid input --------------------------------------------
@given(total=st.integers(min_value=0, max_value=10**12), parts=st.integers(min_value=1, max_value=1000))
@example(total=1, parts=3)  # pinned edge case: always runs, also handy to replay a past failure
def test_split_amount_keeps_every_cent(total, parts):
    shares = split_amount(total, parts)
    assert sum(shares) == total
    assert len(shares) == parts
    assert max(shares) - min(shares) <= 1


# --- 2. round trip: decode(encode(x)) == x ----------------------------------------------------------------
json_values = st.recursive(
    st.none() | st.booleans() | st.integers() | st.text(),
    lambda children: st.lists(children) | st.dictionaries(st.text(), children),
    max_leaves=20,
)


@given(st.dictionaries(st.text(), json_values))
def test_encode_decode_round_trip(data):
    assert decode(encode(data)) == data


# --- 3. oracle: compare with a simple, obviously correct reference -----------------------------------------
@given(st.lists(st.decimals(min_value=0, max_value=10**6, places=2), max_size=50))
def test_total_matches_reference(amounts):
    total_cents = sum(int(a * 100) for a in amounts)
    assert Decimal(total_cents) / 100 == sum(amounts, Decimal(0))
